<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($umkm['name'])?></title><link rel="stylesheet" href="<?=base_url('public/assets/css/template2.css')?>"></head><body><header><div class="brand">🌸 <?=e($umkm['name'])?></div><nav><a href="#home">Home</a><a href="#about">About</a><a href="#products">Products</a><a href="#gallery">Gallery</a><a href="#testi">Testimonials</a><a href="#contact">Contact</a></nav></header><section id="home" class="hero"><div class="hero-copy"><small>FRESH FLOWERS · HANDCRAFTED WITH LOVE</small><h1><?=e($umkm['hero_title'])?></h1><p><?=e($umkm['hero_text'])?></p><a href="#products" class="btn">Lihat Koleksi</a></div><div class="hero-image"><?php if($umkm['hero_image']): ?><img src="<?=base_url('public/'.$umkm['hero_image'])?>"><?php else: ?><div class="flower-placeholder">ROSA<br>GARDEN</div><?php endif; ?></div></section><section id="about" class="about"><div><small>OUR STORY</small><h2>Merangkai Senyuman dengan Tulus</h2></div><p><?=e($umkm['description'])?></p></section><section id="products" class="products"><div class="section-title"><small>OUR COLLECTION</small><h2>Rangkaian Pilihan</h2></div><div class="product-grid"><?php foreach($products as $p): ?><article><div class="product-img"><?php if($p['image']): ?><img src="<?=base_url('public/'.$p['image'])?>"><?php else: ?><span>🌷</span><?php endif; ?></div><div class="product-info"><small><?=e($p['category'])?></small><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><strong><?=money($p['price'])?></strong></div></article><?php endforeach; ?></div></section><section id="testi" class="testi"><small>WARM STORIES OF OUR BLOOMS</small><h2>Kata Mereka</h2><div class="testi-grid"><?php foreach($testimonials as $t): ?><article><div><?=str_repeat('★',(int)$t['rating'])?></div><p>“<?=e($t['message'])?>”</p><b><?=e($t['name'])?></b></article><?php endforeach; ?></div></section><section id="gallery" class="gallery-section"><small>MOMENTS CAPTURED IN BLOSSOMS</small><h2>Galeri Kami</h2><div class="gallery-grid"><?php foreach($gallery as $g): ?><img src="<?=base_url('public/'.$g['image'])?>" alt="<?=e($g['title'])?>"><?php endforeach; ?></div></section><footer id="contact"><h2>Ungkapkan Kasih Sayangmu melalui <?=e($umkm['name'])?></h2><p><?=e($umkm['address'])?> · <?=e($umkm['hours'])?></p><a href="https://wa.me/<?=preg_replace('/\D/','',$umkm['phone'])?>">Konsultasi via WhatsApp</a></footer></body></html>
